1	/**
2	 * `?paint=1` — the approved-artwork chain (round 31): consecutive screens shown as the user's OWN approved pictures, one continuous
3	 * journey. Keyframes in route order (assets/textures/paint/paint.json, tools/paint/): 05k0 = the approved Screen 05 picture,
4	 * 06k0 = the approved Screen 06 picture, 06k1..06k4 = the user's four Screen 06 storyboard panels.
5	 * Each keyframe = a full-screen plate (the picture's own pixels; painted HUD / Benny / collectible coins taken out; margins continued)
6	 * on a depth grid: at its rest moment the view IS the picture; the view eases gently toward the tunnel end as Benny swims.
7	 *  - Benny = each picture's own painted Benny as a layer: steers left/right, leans, bobs; the 3D Benny is hidden while he shows.
8	 *  - Coins = the painted coins as live sprites that flow down the painted river toward Benny, timed by the game's own coin list
9	 *    (overridden for these stages so every painted coin IS a game coin): collected ones pop and vanish, missed ones slide past him.
10	 *  - Picture -> picture: the next picture opens from its tunnel end (soft circle); 3D game -> chain and chain -> 3D game the same way.
11	 * Raw bytes in, raw bytes out (no tone mapping / grade): the painting's colours reach the screen unchanged.
12	 * Off (default): nothing here is built or drawn. `?paint06=1` (paint06.ts) is the earlier Screen-06-only candidate, kept as it was.
13	 */
14	import * as THREE from 'three';
15	import type { Course, StageId } from './course';
16	import type { CoinDef } from '../gameplay/coins';
17	
18	interface CoinPath {
19	  sprite: string; sprite_px: [number, number]; sprite_coin_d: number; stage: StageId; pop_frame_px: [number, number];
20	  D0: number; c: number; samples: [number, number, number, number][]; layout: number[]; lat: number;
21	  /** per coin: visual distance along the painted trail per course unit (1 = the picture's own perspective, Screen 05) */
22	  vscale?: number[];
23	}
24	interface KeyDef {
25	  id: string; screen: StageId; rest: { mark?: string; stage?: StageId; off: number };
26	  files: { plate: string; benny: string; depth: string; flow?: string };
27	  benny_frame_px: [number, number, number, number]; pivot: [number, number]; vp_frame_px: [number, number];
28	  push: number; push_min: number; push_max: number; coins?: CoinPath;
29	  /** the painted water flows toward the viewer inside this mask: px per cycle at the frame bottom, cycles per second */
30	  flow?: { amp: number; rate: number };
31	}
32	interface Layout {
33	  frame: [number, number]; margin: [number, number]; plate_frame_px: [number, number]; plate_scale: number;
34	  keys: KeyDef[]; reveal: Record<string, { stage: StageId; off: number; half: number }>; speed: Record<string, number>;
35	}
36	
37	const sm = (a: number, b: number, x: number) => THREE.MathUtils.smoothstep(x, a, b);
38	const clamp01 = (x: number) => THREE.MathUtils.clamp(x, 0, 1);
39	const asset = (p: string) => { const [dir, name] = p.split('/'); return new URL(`../../assets/textures/${dir}/${name}`, import.meta.url).href; };
40	
41	const FOV = 50;
42	const Z_NEAR = 1.0, Z_FAR = 10.0;
43	const FADE_AT = 0.62, FADE_HALF = 1.7;
44	const FEATHER = 150;
45	const PX_PER_LAT = 66;
46	const CAM_PER_LAT = 0.02;
47	const BENNY_C: [number, number] = [420, 1000];
48	
49	const VERT = /* glsl */ `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`;
50	// Flowing water (keys with a flow mask): the painted water slides away from the tunnel end toward the viewer, two phases half a
51	// cycle apart cross-faded (the design stays the picture's own; at phase 0.5 - every whole second from the QA clock 12.0 - the
52	// offset is zero, so the rest moment is the picture exactly).
53	const FRAG = /* glsl */ `
54	  uniform sampler2D map; uniform float opacity;
55	  uniform vec4 frameMap; uniform vec2 vp; uniform float radius; uniform float feather; uniform float wipe;
56	  uniform sampler2D flowMap; uniform float flowOn; uniform vec2 vpUv; uniform vec2 platePx; uniform float flowAmp; uniform float flowPh;
57	  varying vec2 vUv;
58	  void main(){
59	    vec4 c;
60	    if (flowOn > 0.5) {
61	      float m = texture2D(flowMap, vUv).r;
62	      vec2 dpx = (vUv - vpUv) * platePx; float dl = max(length(dpx), 1.0);
63	      vec2 off = (dpx / dl) * flowAmp * (dl / platePx.y) / platePx * m;
64	      float p1 = flowPh, p2 = fract(flowPh + 0.5);
65	      vec4 c1 = texture2D(map, vUv - off * (p1 - 0.5), -0.45), c2 = texture2D(map, vUv - off * (p2 - 0.5), -0.45);
66	      c = mix(c1, c2, abs(2.0 * p1 - 1.0));
67	    } else c = texture2D(map, vUv, -0.45);
68	    float a = c.a * opacity;
69	    if (wipe != 0.0) {
70	      vec2 F = vec2(gl_FragCoord.x * frameMap.x + frameMap.y, gl_FragCoord.y * frameMap.z + frameMap.w);
71	      float inside = 1.0 - smoothstep(radius - feather, radius, length(F - vp));
72	      a *= wipe > 0.0 ? inside : 1.0 - inside;
73	    }
74	    gl_FragColor = vec4(c.rgb, a);
75	  }`;
76	
77	const qn = (k: string, d: number) => { const v = typeof location === 'undefined' ? null : new URLSearchParams(location.search).get(k); return v !== null && v !== '' && isFinite(+v) ? +v : d; };
78	/** `&paintpush=<f>`: the gentle forward ease toward the tunnel end (1 = as authored); `&paintpan=<f>`: steering parallax (1 = as authored) */
79	// default = scenery holds still (measured: every-frame likeness 82 % / 'looks the same' 93 % in 05 vs 41 % / 54 % with the ease)
80	const PUSH_K = qn('paintpush', 0), PAN_K = qn('paintpan', 0);
81	
82	export async function buildPaint(course: Course, coins: { defs: CoinDef[]; collected: Uint8Array }) {
83	  const L: Layout = await fetch(asset('paint/paint.json')).then((r) => r.json());
84	  const [FW, FH] = L.frame, [MX, MY] = L.margin, [PW, PH] = L.plate_frame_px;
85	  const A0 = FW / FH, tanY = Math.tan(THREE.MathUtils.degToRad(FOV / 2));
86	  const restOf = (K: KeyDef) => (K.rest.mark ? course.marks[K.rest.mark] : course.stage(K.rest.stage as StageId).s0) + K.rest.off;
87	  const rest = L.keys.map(restOf);
88	  const first = L.keys[0], last = L.keys[L.keys.length - 1];
89	  const chainS0 = course.stage(first.screen).s0, chainS1 = course.stage(last.screen).s1;
90	
91	  const loader = new THREE.TextureLoader();
92	  const tex = async (p: string) => {
93	    const t = await loader.loadAsync(asset(p));
94	    t.colorSpace = THREE.NoColorSpace; t.generateMipmaps = true; t.minFilter = THREE.LinearMipmapLinearFilter; t.magFilter = THREE.LinearFilter; t.anisotropy = 4;
95	    return t;
96	  };
97	  const depthOf = async (p: string) => {
98	    const img = await new Promise<HTMLImageElement>((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = asset(p); });
99	    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height;
100	    const g = c.getContext('2d', { willReadFrequently: true })!; g.drawImage(img, 0, 0);
101	    const d = g.getImageData(0, 0, img.width, img.height).data; const out = new Float32Array(img.width * img.height);
102	    for (let i = 0; i < out.length; i++) out[i] = d[i * 4] / 255;
103	    return { w: img.width, h: img.height, d: out };
104	  };
105	  type Depth = Awaited<ReturnType<typeof depthOf>>;
106	  const sampleDepth = (D: Depth, u: number, v: number) => {
107	    const x = THREE.MathUtils.clamp(u * (D.w - 1), 0, D.w - 1), y = THREE.MathUtils.clamp(v * (D.h - 1), 0, D.h - 1);
108	    const x0 = Math.floor(x), y0 = Math.floor(y), x1 = Math.min(x0 + 1, D.w - 1), y1 = Math.min(y0 + 1, D.h - 1), fx = x - x0, fy = y - y0;
109	    return (D.d[y0 * D.w + x0] * (1 - fx) + D.d[y0 * D.w + x1] * fx) * (1 - fy) + (D.d[y1 * D.w + x0] * (1 - fx) + D.d[y1 * D.w + x1] * fx) * fy;
110	  };
111	  const zOf = (d: number) => 1 / (1 / Z_FAR + d * (1 / Z_NEAR - 1 / Z_FAR));
112	  /** frame px at rest -> the 3D point on the rest camera's ray at the plate's depth */
113	  const point = (D: Depth, X: number, Y: number, out: THREE.Vector3) => {
114	    const Z = zOf(sampleDepth(D, (X + MX) / PW, (Y + MY) / PH));
115	    return out.set(((X - FW / 2) / (FW / 2)) * tanY * A0 * Z, -((Y - FH / 2) / (FH / 2)) * tanY * Z, -Z);
116	  };
117	  const NX = 96, NY = 160;
118	  const plateGeometry = (D: Depth) => {
119	    const pos = new Float32Array((NX + 1) * (NY + 1) * 3), uv = new Float32Array((NX + 1) * (NY + 1) * 2); const v3 = new THREE.Vector3();
120	    let p = 0, q = 0;
121	    for (let j = 0; j <= NY; j++) for (let i = 0; i <= NX; i++) {
122	      const u = i / NX, v = j / NY; point(D, u * PW - MX, v * PH - MY, v3);
123	      pos[p++] = v3.x; pos[p++] = v3.y; pos[p++] = v3.z; uv[q++] = u; uv[q++] = 1 - v;
124	    }
125	    const idx: number[] = [];
126	    for (let j = 0; j < NY; j++) for (let i = 0; i < NX; i++) { const a = j * (NX + 1) + i, b = a + 1, c = a + NX + 1, e = c + 1; idx.push(a, c, b, b, c, e); }
127	    const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('uv', new THREE.BufferAttribute(uv, 2)); g.setIndex(idx);
128	    return g;
129	  };
130	  const mat = (map: THREE.Texture) => new THREE.ShaderMaterial({
131	    uniforms: { map: { value: map }, opacity: { value: 1 }, frameMap: { value: new THREE.Vector4() }, vp: { value: new THREE.Vector2() }, radius: { value: 0 }, feather: { value: FEATHER }, wipe: { value: 0 },
132	      flowMap: { value: null as THREE.Texture | null }, flowOn: { value: 0 }, vpUv: { value: new THREE.Vector2() }, platePx: { value: new THREE.Vector2(PW, PH) }, flowAmp: { value: 0 }, flowPh: { value: 0.5 } },
133	    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthTest: false, depthWrite: false, toneMapped: false, side: THREE.DoubleSide,
134	  });
135	
136	  const scene = new THREE.Scene();
137	  const cam = new THREE.PerspectiveCamera(FOV, A0, 0.02, 100);
138	  const oScene = new THREE.Scene();
139	  const oCam = new THREE.OrthographicCamera(-FW / 2, FW / 2, FH / 2, -FH / 2, -10, 10);
140	
141	  // ---------------------------------------------------------------- coins: the painted coins ARE the game's coins on these stages
142	  const coinKeys = new Map<number, number>(); // coin index -> key index
143	  const vscaleOf = new Map<number, number>();
144	  const queues = new Map<StageId, number[]>();
145	  for (const K of L.keys) if (K.coins && !queues.has(K.coins.stage))
146	    queues.set(K.coins.stage, coins.defs.map((d, i) => [d, i] as const).filter(([d]) => d.stage === K.coins!.stage).sort((a, b) => a[0].s - b[0].s).map(([, i]) => i));
147	  L.keys.forEach((K, k) => {
148	    if (!K.coins) return;
149	    const q = queues.get(K.coins.stage)!;
150	    K.coins.layout.forEach((dl, n) => {
151	      const i = q.shift(); if (i === undefined) return;
152	      coins.defs[i].s = rest[k] + dl; coins.defs[i].lat = K.coins!.lat; coinKeys.set(i, k); vscaleOf.set(i, K.coins!.vscale?.[n] ?? 1);
153	    });
154	  });
155	  // game coins of these stages with no painted coin: moved out of the course (never shown, never counted, also after QA resets)
156	  for (const q of queues.values()) for (const i of q) { coins.defs[i].s = -1000 - i; coins.collected[i] = 1; }
157	
158	  const keys = await Promise.all(L.keys.map(async (K) => {
159	    const [plate, benny, depth, flow] = await Promise.all([tex(K.files.plate), tex(K.files.benny), depthOf(K.files.depth), K.files.flow ? tex(K.files.flow) : Promise.resolve(null)]);
160	    const mesh = new THREE.Mesh(plateGeometry(depth), mat(plate)); mesh.frustumCulled = false; mesh.visible = false; scene.add(mesh);
161	    if (flow && K.flow) {
162	      const U = (mesh.material as THREE.ShaderMaterial).uniforms;
163	      U.flowMap.value = flow; U.flowOn.value = 1; U.flowAmp.value = K.flow.amp;
164	      U.vpUv.value.set((K.vp_frame_px[0] + MX) / PW, 1 - (K.vp_frame_px[1] + MY) / PH);
165	    }
166	    const [bx0, by0, bx1, by1] = K.benny_frame_px, bw = bx1 - bx0, bh = by1 - by0, [px, py] = K.pivot;
167	    const pivot = new THREE.Group(); const quad = new THREE.Mesh(new THREE.PlaneGeometry(bw, bh), mat(benny));
168	    quad.position.set(bx0 + bw / 2 - px, -(by0 + bh / 2 - py), 0); pivot.add(quad); pivot.visible = false; oScene.add(pivot);
169	    const [vx, vy] = K.vp_frame_px;
170	    const pushDir = new THREE.Vector3(((vx - FW / 2) / (FW / 2)) * tanY * A0, -((vy - FH / 2) / (FH / 2)) * tanY, -1).normalize();
171	    let rMax = 0;
172	    for (const [cx, cy] of [[-MX, -MY], [FW + MX, -MY], [-MX, FH + MY], [FW + MX, FH + MY]]) rMax = Math.max(rMax, Math.hypot(cx - vx, cy - vy));
173	    let coin: { tex: THREE.Texture; geo: THREE.PlaneGeometry; meshes: Map<number, THREE.Mesh>; P: CoinPath } | null = null;
174	    if (K.coins) {
175	      const ct = await tex(K.coins.sprite);
176	      coin = { tex: ct, geo: new THREE.PlaneGeometry(1, 1), meshes: new Map(), P: K.coins };
177	    }
178	    return { K, mesh, depth, pivot, quad, vp: new THREE.Vector2(vx, vy), pushDir, rMax: rMax + FEATHER, coin };
179	  }));
180	  // one sprite mesh per coin of each key (shared texture); kept in `scene`, toggled per render
181	  const pops = new Map<number, THREE.Mesh>();
182	  keys.forEach((Q) => {
183	    if (!Q.coin) return;
184	    for (const [i, k] of coinKeys) if (keys[k] === Q) {
185	      const m = new THREE.Mesh(Q.coin.geo, mat(Q.coin.tex)); m.visible = false; m.frustumCulled = false; scene.add(m); Q.coin.meshes.set(i, m);
186	      const pm = new THREE.Mesh(Q.coin.geo, mat(Q.coin.tex)); pm.visible = false; oScene.add(pm); pops.set(i, pm);
187	    }
188	  });
189	
190	  /** path of a coin d course units ahead of Benny, at rest (frame px x, y, diameter) */
191	  const pathAt = (P: CoinPath, d: number): [number, number, number] => {
192	    const sm_ = P.samples, d0 = sm_[0][0], step = sm_[1][0] - sm_[0][0];
193	    const f = THREE.MathUtils.clamp((d - d0) / step, 0, sm_.length - 1.001), i = Math.floor(f), t = f - i;
194	    const a = sm_[i], b = sm_[i + 1];
195	    return [a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, a[3] + (b[3] - a[3]) * t];
196	  };
197	
198	  // ---------------------------------------------------------------- timeline
199	  const joinIn = (s: number) => clamp01((s - (chainS0 - 2.0)) / 4.5);
200	  const joinOut = (s: number) => clamp01((s - (chainS1 - 1.0)) / 5.0);
201	  const revealC = L.keys.map((K, k) => {
202	    if (k === 0) return [0, 0];
203	    const r = L.reveal[K.id];
204	    if (r) return [course.stage(r.stage).s0 + r.off, r.half];
205	    return [rest[k - 1] + FADE_AT * (rest[k] - rest[k - 1]), FADE_HALF];
206	  });
207	  const keyProg = (k: number, s: number) => (k === 0 ? 1 : clamp01((s - (revealC[k][0] - revealC[k][1])) / (2 * revealC[k][1])));
208	  const radiusAt = (Q: { rMax: number }, f: number) => Q.rMax * Math.pow(f, 1.35);
209	  const insideAt = (Q: { vp: THREE.Vector2; rMax: number }, f: number, x: number, y: number) => { const r = radiusAt(Q, f); return 1 - sm(r - FEATHER, r, Math.hypot(x - Q.vp.x, y - Q.vp.y)); };
210	  const weight = (s: number) => (joinIn(s) <= 0 || joinOut(s) >= 1 ? 0 : joinIn(s) >= 1 && joinOut(s) <= 0 ? 1 : 0.5);
211	  const speedK = (s: number) => {
212	    let k = 1;
213	    for (const [id, f] of Object.entries(L.speed)) { const st = course.stage(id as StageId); k *= 1 + (f - 1) * sm(st.s0 - 4, st.s0 + 1, s) * (1 - sm(st.s1 - 2, st.s1 + 3, s)); }
214	    return k;
215	  };
216	  const paintBenny = (s: number) => {
217	    const fin = joinIn(s), fout = joinOut(s);
218	    if (fin <= 0 || fout >= 1) return 0;
219	    if (fin < 1) return insideAt(keys[0], fin, BENNY_C[0], BENNY_C[1]);
220	    if (fout > 0) return 1 - insideAt(keys[keys.length - 1], fout, BENNY_C[0], BENNY_C[1]);
221	    return 1;
222	  };
223	
224	  const popStart = new Float32Array(coins.defs.length).fill(-1);
225	  const size = new THREE.Vector2(), buf = new THREE.Vector2(), v3 = new THREE.Vector3();
226	  const draw = (renderer: THREE.WebGLRenderer, o: { s: number; lat: number; steer: number; time: number; clock: number }) => {
227	    renderer.getSize(size); renderer.getDrawingBufferSize(buf);
228	    const a = size.x / Math.max(1, size.y);
229	    let hx = tanY * A0, hy = tanY;
230	    if (a >= A0) { hy = tanY; hx = hy * a; const mx = tanY * A0 * (1 + MX / (FW / 2)); if (hx > mx) { hx = mx; hy = hx / a; } }
231	    else { hx = tanY * A0; hy = hx / a; const my = tanY * (1 + MY / (FH / 2)); if (hy > my) { hy = my; hx = hy * a; } }
232	    cam.aspect = a; cam.fov = THREE.MathUtils.radToDeg(2 * Math.atan(hy)); cam.updateProjectionMatrix();
233	    const ex = (hx / (tanY * A0)) * FW / 2, ey = (hy / tanY) * FH / 2;
234	    oCam.left = -ex; oCam.right = ex; oCam.top = ey; oCam.bottom = -ey; oCam.updateProjectionMatrix();
235	    const fm = new THREE.Vector4(2 * ex / buf.x, FW / 2 - ex, -2 * ey / buf.y, FH / 2 + ey);
236	    const fin = joinIn(o.s), fout = joinOut(o.s);
237	    if (fin <= 0 || fout >= 1) return;
238	    const prevAuto = renderer.autoClear; renderer.autoClear = false; renderer.setRenderTarget(null);
239	    if (fin >= 1 && fout <= 0) renderer.clear(true, true, true);
240	    let k0 = 0;
241	    for (let k = keys.length - 1; k >= 0; k--) if (keyProg(k, o.s) >= 1) { k0 = k; break; }
242	    let k1 = k0;
243	    for (let k = k0 + 1; k < keys.length; k++) if (keyProg(k, o.s) > 0) k1 = k;
244	    const camX = PAN_K * THREE.MathUtils.clamp(o.lat * CAM_PER_LAT, -0.07, 0.07);
245	    const wipeOf = (k: number): [number, number] => {
246	      if (k === 0 && fin < 1) return [1, fin];
247	      if (k > k0) return [1, keyProg(k, o.s)];
248	      if (k === keys.length - 1 && fout > 0) return [-1, fout];
249	      return [0, 1];
250	    };
251	    const setCam = (k: number) => {
252	      const Q = keys[k], z = PUSH_K * THREE.MathUtils.clamp((o.s - rest[k]) * Q.K.push, Q.K.push_min, Q.K.push_max);
253	      cam.position.copy(Q.pushDir).multiplyScalar(z / Math.abs(Q.pushDir.z)); cam.position.x += camX;
254	      cam.lookAt(cam.position.x, cam.position.y, cam.position.z - 1); cam.updateMatrixWorld();
255	    };
256	    const hideAll = () => scene.children.forEach((c) => { c.visible = false; });
257	    const setU = (m: THREE.Mesh, op: number, mode: number, f: number, Q: (typeof keys)[number]) => {
258	      const U = (m.material as THREE.ShaderMaterial).uniforms;
259	      U.opacity.value = op; U.wipe.value = mode; U.radius.value = radiusAt(Q, f); U.vp.value.copy(Q.vp); U.frameMap.value.copy(fm);
260	    };
261	    /** coins of key k: which = 'back' (ahead of Benny) | 'front' (passed him / popping) */
262	    const drawCoins = (k: number, which: 'back' | 'front', mode: number, f: number) => {
263	      const Q = keys[k]; if (!Q.coin) return;
264	      hideAll(); let any = false;
265	      const P = Q.coin.P, list: [number, THREE.Mesh][] = [];
266	      for (const [i, m] of Q.coin.meshes) {
267	        const def = coins.defs[i], col = coins.collected[i] === 1;
268	        const d = (def.s - o.s) * (vscaleOf.get(i) ?? 1); let op = 1; const lift = 0, grow = 1;
269	        if (col) continue; // collected: shown as the pop above his pom-pom (ortho, after Benny)
270	        {
271	          if (d > P.samples[P.samples.length - 1][0] || d < P.samples[0][0]) continue;
272	          if ((which === 'back') !== (d > 0.3)) continue;
273	          op = clamp01((P.samples[P.samples.length - 1][0] - d) / 6);
274	        }
275	        const [x, y, dia0] = pathAt(P, d);
276	        const ppu = PX_PER_LAT * (P.D0 / Math.max(0.35, d + P.D0));
277	        let X = x + (def.lat - P.lat) * ppu; const Y = y - lift;
278	        // a coin he steered away from passes visibly BESIDE him (never through his body) and fades before it grows huge
279	        const dia = Math.min(dia0, 1.5 * P.sprite_coin_d);
280	        if (d < 1.0) {
281	          const bx = Q.K.pivot[0] + o.lat * PX_PER_LAT, dx = X - bx, clear = 185 + dia / 2;
282	          if (Math.abs(dx) < clear) X = bx + Math.sign(dx || -1) * (Math.abs(dx) + (clear - Math.abs(dx)) * clamp01((1.0 - d) / 0.8));
283	        }
284	        if (d < -0.8) op *= clamp01((d + 2.4) / 1.6);
285	        if (op <= 0.01) continue;
286	        point(Q.depth, X, Math.min(Y, FH + MY - 2), v3);
287	        const Z = -v3.z, hWorld = (dia * grow / (FH / 2)) * tanY * Z;
288	        m.position.copy(v3); m.scale.set(hWorld * (P.sprite_px[0] / P.sprite_coin_d), hWorld * (P.sprite_px[1] / P.sprite_coin_d), 1);
289	        setU(m, op, mode, f, Q); m.visible = true; m.renderOrder = -d; list.push([d, m]); any = true;
290	      }
291	      if (!any) return;
292	      list.sort((p, q) => q[0] - p[0]); list.forEach(([, m], n) => { m.renderOrder = n; });
293	      renderer.render(scene, cam);
294	    };
295	    // plates (+ the coins still ahead of Benny), oldest first
296	    for (let k = k0; k <= k1; k++) {
297	      const Q = keys[k]; setCam(k);
298	      const [mode, f] = wipeOf(k);
299	      hideAll(); Q.mesh.visible = true; setU(Q.mesh, 1, mode, f, Q);
300	      if (Q.K.flow) (Q.mesh.material as THREE.ShaderMaterial).uniforms.flowPh.value = ((((o.time - 12.0) * Q.K.flow.rate + 0.5) % 1) + 1) % 1;
301	      renderer.render(scene, cam);
302	      drawCoins(k, 'back', mode, f);
303	    }
304	    // Benny: each picture's own painted Benny, switched where the reveal edge passes his centre
305	    const bob = Math.sin(o.time * Math.PI) * 2.5;
306	    for (let k = k0; k <= k1; k++) {
307	      const Q = keys[k]; const [mode, f] = wipeOf(k);
308	      const ins = mode === 0 ? 1 : insideAt(Q, f, BENNY_C[0], BENNY_C[1]); const al = mode < 0 ? 1 - ins : ins;
309	      if (al <= 0.001) continue;
310	      for (const R of keys) R.pivot.visible = R === Q;
311	      Q.pivot.position.set(Q.K.pivot[0] - FW / 2 + o.lat * PX_PER_LAT, FH / 2 - Q.K.pivot[1] + bob, 0); Q.pivot.rotation.z = -o.steer * 0.16;
312	      const U = (Q.quad.material as THREE.ShaderMaterial).uniforms; U.opacity.value = al; U.wipe.value = 0;
313	      renderer.render(oScene, oCam);
314	    }
315	    for (const R of keys) R.pivot.visible = false;
316	    // coins that have passed him: in front of Benny
317	    for (let k = k0; k <= k1; k++) { setCam(k); const [mode, f] = wipeOf(k); drawCoins(k, 'front', mode, f); }
318	    // collected coins: a small coin flies up from his pom-pom and fades (0.4 s) — only coins collected in play just now
319	    let anyPop = false;
320	    oScene.children.forEach((c) => { if (c !== undefined && (c as THREE.Mesh).isMesh) c.visible = false; });
321	    for (const [i, pm] of pops) {
322	      if (coins.collected[i] !== 1) { popStart[i] = -1; continue; }
323	      if (popStart[i] < 0) { if (Math.abs(coins.defs[i].s - o.s) > 1.6) { popStart[i] = -2; continue; } popStart[i] = o.clock; }
