327	      const dia = 58 * (1 - 0.55 * t);
328	      pm.scale.set(dia * P.sprite_px[0] / P.sprite_coin_d, dia * P.sprite_px[1] / P.sprite_coin_d, 1);
329	      pm.position.set(P.pop_frame_px[0] - FW / 2 + o.lat * PX_PER_LAT, FH / 2 - (P.pop_frame_px[1] - 170 * t), 0);
330	      const U = (pm.material as THREE.ShaderMaterial).uniforms; U.opacity.value = 1 - t * t; U.wipe.value = 0;
331	      pm.visible = true; anyPop = true;
332	    }
333	    if (anyPop) renderer.render(oScene, oCam);
334	    for (const pm of pops.values()) pm.visible = false;
335	    hideAll();
336	    renderer.autoClear = prevAuto;
337	  };
338	  /** QA: frame px of every visible coin of the current picture (at rest, before the gentle push) */
339	  const coinInfo = (s: number) => {
340	    const out: { i: number; d: number; x: number; y: number; dia: number; collected: boolean }[] = [];
341	    keys.forEach((Q) => { if (!Q.coin) return; for (const [i] of Q.coin.meshes) { const d = (coins.defs[i].s - s) * (vscaleOf.get(i) ?? 1); const [x, y, dia] = pathAt(Q.coin.P, d); out.push({ i, d: +d.toFixed(2), x: +x.toFixed(1), y: +y.toFixed(1), dia: +dia.toFixed(1), collected: coins.collected[i] === 1 }); } });
342	    return out;
343	  };
344	  return { weight, speedK, draw, paintBenny, rest, keyIds: L.keys.map((K) => K.id), coinInfo, chainS0, chainS1 };
345	}
346	export type Paint = Awaited<ReturnType<typeof buildPaint>>;
