r = b31rot(r, vec3(0.0, 0.0, 1.0), uPom.y * wp);
p = pp + r;
// squash with the stroke (bottom stays on the water)
float sq = 1.0 + 0.03 * uSwim * sin(uT * 15.0);
p.y = (p.y + 0.5) * sq - 0.5; p.xz /= sqrt(sq);
vec3 transformed = p;
`;

